import { Column, Entity, PrimaryColumn } from 'typeorm';

/**
 * One row of `public.media` (migration `0014_media.sql`; data-model `media`; decision 0009 section
 * 8). `contentType` is the type detected from the uploaded bytes, `bytes` the uploaded size,
 * `width` and `height` those of the oriented master. Columns state `type` and `name` explicitly
 * (decision 0007 sections 2 and 8).
 */
@Entity({ name: 'media', schema: 'public' })
export class Media {
  /** UUIDv7 generated by the API before the insert: the object keys need it. */
  @PrimaryColumn({ type: 'uuid', name: 'id', default: () => 'uuidv7()' })
  id!: string;

  /** `media/<yyyy>/<mm>/<id>`; never returned to a client. */
  @Column({ type: 'text', name: 'storage_key' })
  storageKey!: string;

  @Column({ type: 'text', name: 'content_type' })
  contentType!: string;

  @Column({ type: 'integer', name: 'width' })
  width!: number;

  @Column({ type: 'integer', name: 'height' })
  height!: number;

  @Column({ type: 'integer', name: 'bytes' })
  bytes!: number;

  @Column({ type: 'text', name: 'sha256' })
  sha256!: string;

  @Column({ type: 'text', name: 'blurhash' })
  blurhash!: string;

  @Column({ type: 'text', name: 'alt_text', nullable: true })
  altText!: string | null;

  /** References `users`; null only for a row written by the seed. */
  @Column({ type: 'uuid', name: 'uploaded_by', nullable: true })
  uploadedBy!: string | null;

  @Column({ type: 'timestamptz', name: 'created_at', default: () => 'now()' })
  createdAt!: Date;
}
